mapper.select:
SELECT t.id AS teacherId, t.teacher_no AS teacherNo, t.teacher_name AS teacherName, term.id AS termId, term.term_name AS termName, totalSta.total AS totalLessonHours, COUNT(DISTINCT CASE WHEN sd.session_status = 2 AND cc.teacher_id = sd.teacher_id THEN sd.id END) AS completedLessonHours, tk.tkNum AS adjustedSessions, dk.dkNum AS substituteSessions FROM t_as_course_session sd INNER JOIN t_as_course_class cc on cc.id = sd.course_class_id and cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_as_teacher t ON sd.teacher_id = t.id AND t.is_valid = 1 INNER JOIN t_educl_term term ON svc.term_id = term.id LEFT JOIN (select cs.original_teacher_id,s.term_id,count(cs.id) AS total from t_as_course_session cs LEFT JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.is_valid = 1 LEFT JOIN t_as_service s on s.id = cc.service_id and s.is_valid = 1 where cs.school_id = #{query.schoolId} and cs.is_valid = 1 GROUP BY cs.original_teacher_id,s.term_id ) totalSta on totalSta.original_teacher_id = sd.teacher_id and totalSta.term_id = svc.term_id LEFT JOIN (SELECT svc.term_id, cc.teacher_id, count(cs.id) AS tkNum FROM t_as_course_session cs INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.teacher_id != cs.teacher_id and cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cs.school_id = #{query.schoolId} AND cs.is_valid = 1 AND cs.adjust_status = 1 and cs.session_status = 2 GROUP BY cc.teacher_id,svc.term_id ) tk on tk.teacher_id = cc.teacher_id and tk.term_id = svc.term_id LEFT JOIN (SELECT svc.term_id, cs.teacher_id, count(cs.id) AS dkNum FROM t_as_course_session cs INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.teacher_id != cs.teacher_id and cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cs.school_id = #{query.schoolId} AND cs.is_valid = 1 AND cs.adjust_status = 1 and cs.session_status = 2 GROUP BY cs.teacher_id,svc.term_id ) dk on dk.term_id = svc.term_id and dk.teacher_id = sd.teacher_id
sd.is_valid = 1
AND sd.school_id = #{query.schoolId}
AND svc.term_id = #{query.termId}
AND (t.teacher_name LIKE CONCAT('%', #{query.queryInfo}, '%') OR t.teacher_no LIKE CONCAT('%', #{query.queryInfo}, '%'))
GROUP BY t.id, term.id ORDER BY t.teacher_name ASC

SELECT stu.id AS studentId, si.id AS studentIdentityId, stu.student_no AS studentNo, stu.student_name AS studentName, term.id AS termId, term.term_name AS termName, GROUP_CONCAT(DISTINCT cc.course_class_name SEPARATOR ';') AS courseClassNames, GROUP_CONCAT(DISTINCT cat.category_name SEPARATOR ';') AS courseCategoryNames, COUNT(DISTINCT sd.id) AS totalLessonHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status NOT IN (4, 5) THEN sd.id END) AS attendanceHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status IN (4, 5) THEN sd.id END) AS absenceHours FROM t_as_student stu INNER JOIN t_as_student_identity si ON si.id = stu.student_identity_id AND si.is_valid = 1 INNER JOIN t_as_student_destination dest ON stu.id = dest.student_id AND dest.is_valid = 1 AND dest.destination_type = 1 INNER JOIN t_as_course_session sd ON dest.session_id = sd.id AND sd.is_valid = 1 INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_course_category cat ON cat.id = cc.category_id AND cat.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_educl_term term ON svc.term_id = term.id LEFT JOIN t_as_attendance_record att ON att.session_id = sd.id AND att.student_id = stu.id AND att.is_valid = 1 and att.target_type = 1
stu.is_valid = 1 and stu.register_status = 1 AND stu.term_id = svc.term_id
AND stu.school_id = #{query.schoolId}
AND (stu.student_name LIKE CONCAT('%', #{query.queryInfo}, '%') OR stu.student_no LIKE CONCAT('%', #{query.queryInfo}, '%'))
AND svc.term_id = #{query.termId}
GROUP BY stu.id, term.id,stu.student_no,stu.student_name,term.term_name HAVING 1=1
AND COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status IN (4, 5) THEN sd.id END) >= #{query.minAbsenceHours}
ORDER BY stu.student_name ASC

SELECT sd.school_id AS schoolId, sd.id AS sessionId, sd.session_date AS sessionDate, CONCAT(DATE_FORMAT(sd.start_time, '%H:%i') , '-', DATE_FORMAT(sd.end_time, '%H:%i')) AS sessionTime, cc.id AS courseClassId, cc.course_class_name AS courseClassName, cc.applicable_grade_ids AS applicableGradeIds, cc.applicable_class_ids AS applicableClassIds, CASE WHEN sd.teacher_id != cc.teacher_id THEN 1 ELSE 2 END AS lessonType FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_teacher t_sub ON sd.teacher_id = t_sub.id AND t_sub.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
sd.is_valid = 1 AND sd.session_status = 2 AND NOW() > STR_TO_DATE(CONCAT(sd.session_date, ' ', sd.start_time, '%H:%i:%s'), '%Y-%m-%d %H:%i:%s') AND sd.teacher_id = #{query.teacherId} AND svc.term_id = #{query.termId}
AND DATE(sd.session_date) BETWEEN DATE(#{query.sessionDateStart}) AND DATE(#{query.sessionDateEnd})
AND cc.id = #{query.courseClassId}
AND ((cc.enroll_type IN (1, 2)AND (JSON_CONTAINS(cc.applicable_grade_ids,CAST(#{query.gradeId} AS JSON)))) OR(cc.enroll_type = 3 AND EXISTS (SELECT 1 FROM t_educl_class ec WHERE ec.is_valid = 1 AND ec.school_id = cc.school_id AND JSON_CONTAINS(cc.applicable_class_ids,CAST(ec.id AS JSON)) AND ec.grade_id = #{query.gradeId})))
ORDER BY sd.session_date DESC

SELECT distinct term.id AS termId, term.term_name AS termName, sd.id AS sessionId, sd.session_date AS sessionDate, cc.course_class_name AS courseClassName, CONCAT(DATE_FORMAT(sd.start_time, '%H:%i') , '-', DATE_FORMAT(sd.end_time, '%H:%i')) AS sessionTime, att.attendance_status AS attendanceStatus, wr.exception_desc AS remark FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_term term ON svc.term_id = term.id AND term.is_valid = 1 INNER JOIN t_as_student_destination dest ON dest.session_id = sd.id AND dest.is_valid = 1 AND dest.destination_type = 1 INNER JOIN t_as_student stu ON dest.student_id = stu.id AND stu.is_valid = 1 AND stu.term_id = svc.term_id INNER JOIN t_as_attendance_record att ON dest.session_id = att.session_id AND att.student_id = dest.student_id AND att.is_valid = 1 AND att.target_type = 1 LEFT JOIN t_as_warning_record wr ON wr.student_id = dest.student_id AND dest.session_id = wr.session_id AND wr.is_valid = 1
sd.is_valid = 1 AND NOW() > STR_TO_DATE(CONCAT(sd.session_date, ' ', sd.start_time, '%H:%i:%s'), '%Y-%m-%d %H:%i:%s') AND dest.student_id = #{query.studentId} AND svc.term_id = #{query.termId}
AND sd.school_id = #{query.schoolId}
AND DATE(sd.session_date) BETWEEN DATE(#{query.sessionDateStart}) AND DATE(#{query.sessionDateEnd})
AND att.attendance_status = #{query.attendanceStatus}
ORDER BY sd.session_date DESC

SELECT dest.student_id AS studentId, GROUP_CONCAT(DISTINCT cc.course_class_name SEPARATOR ';') AS courseClassNames, GROUP_CONCAT(DISTINCT cat.category_name SEPARATOR ';') AS categoryNames, COUNT(DISTINCT sd.id) AS totalLessonHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status NOT IN (4, 5) THEN sd.id END) AS attendanceHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status IN (4, 5) THEN sd.id END) AS absenceHours FROM t_as_student stu INNER JOIN t_as_student_destination dest ON stu.id = dest.student_id AND dest.is_valid = 1 AND dest.destination_type = 1 INNER JOIN t_as_course_session sd ON dest.session_id = sd.id AND sd.is_valid = 1 LEFT JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cat.id = cc.category_id AND cat.is_valid = 1 LEFT JOIN t_as_attendance_record att ON att.session_id = sd.id AND att.student_id = stu.id AND att.is_valid = 1 AND att.target_type = 1 WHERE stu.is_valid = 1 AND stu.id IN
#{id}
GROUP BY dest.student_id

SELECT DATE_FORMAT(sd.session_date, '%Y年%m月') AS month, COUNT(DISTINCT sd.id) AS totalHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status NOT IN (4, 5) THEN sd.id END) AS attendanceHours, COUNT(DISTINCT CASE WHEN att.id IS NOT NULL AND att.attendance_status IN (4, 5) THEN sd.id END) AS absenceHours FROM t_as_student stu INNER JOIN t_as_student_destination dest ON stu.id = dest.student_id AND dest.is_valid = 1 AND dest.destination_type = 1 INNER JOIN t_as_course_session sd ON dest.session_id = sd.id AND sd.is_valid = 1 INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_attendance_record att ON att.session_id = sd.id AND att.student_id = stu.id AND att.is_valid = 1 AND att.target_type = 1 WHERE stu.is_valid = 1 AND stu.id = #{query.studentId} AND stu.term_id = #{query.termId} AND svc.term_id = #{query.termId}
AND DATE_FORMAT(sd.session_date, '%Y-%m') BETWEEN #{query.cqqsSessionDateStart} AND #{query.cqqsSessionDateEnd}
GROUP BY DATE_FORMAT(sd.session_date, '%Y年%m月') ORDER BY DATE_FORMAT(sd.session_date, '%Y-%m') ASC

SELECT cc.course_class_name AS courseClassName, COUNT(DISTINCT sd.id) AS lessonCount FROM t_as_student stu INNER JOIN t_as_student_destination dest ON stu.id = dest.student_id AND dest.is_valid = 1 AND dest.destination_type = 1 INNER JOIN t_as_course_session sd ON dest.session_id = sd.id AND sd.is_valid = 1 INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE stu.is_valid = 1 and stu.register_status = 1 AND stu.id = #{query.studentId} AND stu.term_id = #{query.termId} AND svc.term_id = #{query.termId}
AND DATE_FORMAT(sd.session_date, '%Y-%m') BETWEEN DATE_FORMAT(#{query.ksfbSessionDateStart}, '%Y-%m') AND DATE_FORMAT(#{query.ksfbSessionDateEnd}, '%Y-%m')
GROUP BY cc.id

SELECT COUNT(DISTINCT CASE WHEN sd.teacher_id = cc.teacher_id THEN sd.id END) AS attendanceHours, COUNT(DISTINCT CASE WHEN sd.adjust_status = 1 and sd.teacher_id != cc.teacher_id THEN sd.id END) AS adjustHours FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE sd.is_valid = 1 and sd.session_status = 2
AND svc.term_id = #{termId}
AND DATE(sd.session_date) <= CURDATE()

SELECT DATE_FORMAT(sd.session_date, '%Y年%m月') AS month, COUNT(DISTINCT sd.id) AS totalSessions, COUNT(DISTINCT CASE WHEN sd.session_status = 2 THEN sd.id END) AS attendedSessions FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE sd.is_valid = 1
AND svc.term_id = #{termId}
AND DATE(sd.session_date) <= CURDATE() GROUP BY DATE_FORMAT(sd.session_date, '%Y年%m月') ORDER BY DATE_FORMAT(sd.session_date, '%Y-%m') ASC

SELECT
    (SELECT COUNT(distinct student_no) from t_as_student where is_valid = 1 and term_id = #{termId} and school_id = #{schoolId} and school_roll_status = 1
    ) AS totalStudentCount,
    (SELECT COUNT(distinct student_no) from t_as_student where is_valid = 1 and term_id = #{termId} and school_id = #{schoolId} and school_roll_status = 1 and register_status = 1
    ) AS registeredStudentCount,
    (SELECT COUNT(distinct student_no) from t_as_student where is_valid = 1 and term_id = #{termId} and school_id = #{schoolId} and school_roll_status = 1 and register_status = 0
    ) AS pendingStudentCount,
    (SELECT COUNT(*) FROM t_educl_class c
     WHERE c.is_valid = 1 AND c.school_id = #{schoolId} AND c.term_id = #{termId}
    ) AS classCount,
    (SELECT COUNT(*) FROM t_as_teacher t
     WHERE t.is_valid = 1 AND t.school_id = #{schoolId} and t.employee_status = 1
    ) AS teacherCount,
    (SELECT COUNT(*) FROM t_as_course_class cc
     WHERE cc.is_valid = 1 AND cc.school_id = #{schoolId} AND cc.enroll_type = 3
    ) AS adminCourseCount,
    (SELECT COUNT(DISTINCT cc.id) FROM t_as_course_class cc
    INNER JOIN t_as_service s on s.id = cc.service_id and s.is_valid = 1 and s.service_status != 0
    WHERE cc.is_valid = 1 AND cc.school_id = #{schoolId} AND s.term_id = #{termId}
    ) AS afterSchoolCourseCount,
    (SELECT COUNT(DISTINCT ar.id) FROM t_as_attendance_record ar
    INNER JOIN t_as_course_session cs on cs.id = ar.session_id  and cs.is_valid = 1
    INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.is_valid = 1
    INNER JOIN t_as_service s on s.id = cc.service_id and s.is_valid = 1
    WHERE ar.is_valid = 1 AND ar.school_id = #{schoolId} AND s.term_id = #{termId}
    AND ar.target_type = 1 AND ar.attendance_status in (1,2,3)
    ) AS attendancePresentCount,
    (SELECT COUNT(DISTINCT ar.id) FROM t_as_attendance_record ar
    INNER JOIN t_as_course_session cs on cs.id = ar.session_id  and cs.is_valid = 1
    INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.is_valid = 1
    INNER JOIN t_as_service s on s.id = cc.service_id and s.is_valid = 1
    WHERE ar.is_valid = 1 AND ar.school_id = #{schoolId} AND s.term_id = #{termId}
    AND ar.target_type = 1
    ) AS attendanceTotalCount

SELECT IFNULL(cat.category_name, '未分类') AS name, COUNT(DISTINCT cs.id) AS value FROM t_as_course_session cs INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 WHERE cs.is_valid = 1
AND cs.school_id = #{schoolId}
AND svc.term_id = #{termId}
GROUP BY cc.category_id ORDER BY value DESC

SELECT
    DATE_FORMAT(cs.session_date, '%Y年%m月') AS month,
    COUNT(cs.id) AS lessonCount
FROM t_as_course_session cs
INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1
INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
WHERE cs.is_valid = 1 and cs.session_status = 2

    AND cs.school_id = #{schoolId}


    AND svc.term_id = #{termId}


    AND cs.session_date >= #{startDate}


    AND cs.session_date <= #{endDate}

GROUP BY DATE_FORMAT(cs.session_date, '%Y年%m月')
ORDER BY DATE_FORMAT(cs.session_date, '%Y-%m') ASC

SELECT ar.attendance_status AS attendanceStatus, COUNT(ar.id) AS cnt FROM t_as_attendance_record ar INNER JOIN t_as_course_session cs ON ar.session_id = cs.id AND cs.is_valid = 1 INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_as_student s ON ar.student_id = s.id AND s.is_valid = 1 AND s.term_id = svc.term_id WHERE ar.is_valid = 1 AND ar.target_type = 1 AND ar.school_id = #{schoolId} AND svc.term_id = #{termId}
AND DATE(cs.session_date) BETWEEN DATE(#{kqfbSessionStartDate}) AND DATE(#{kqfbSessionEndDate})
GROUP BY ar.attendance_status

SELECT s.grade_id AS gradeId, g.grade_name AS gradeName, COUNT(distinct e.student_id) AS cnt FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 and s.register_status = 1 INNER JOIN t_as_service svc ON e.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_source != 3 AND e.enroll_status IN (1, 3, 4) AND e.school_id = #{schoolId} AND s.term_id = svc.term_id
AND svc.term_id = #{tskcfbTermId}
GROUP BY s.grade_id ORDER BY g.sort_no ASC

SELECT s.grade_id AS gradeId, g.grade_name AS gradeName, COUNT(distinct e.student_id) AS cnt FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 and s.register_status = 1 INNER JOIN t_as_service svc ON e.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_source = 3 AND e.enroll_status IN (1, 3, 4) AND e.school_id = #{schoolId} AND s.term_id = svc.term_id
AND svc.term_id = #{xzkcfbTermId}
GROUP BY s.grade_id, g.grade_name ORDER BY g.sort_no ASC

SELECT CASE cc.enroll_type WHEN 1 THEN '公开选课' WHEN 2 THEN '邀请选课' WHEN 3 THEN '行政安排' END AS name, COUNT(DISTINCT e.student_id) AS value FROM t_as_enrollment e INNER JOIN t_as_course_class cc on cc.id = e.course_class_id and cc.is_valid = 1 INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 and s.register_status = 1 INNER JOIN t_as_service svc ON e.service_id = svc.id AND svc.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_status in (1,3) AND e.school_id = #{schoolId}
AND svc.term_id = #{xsxkTermId}
GROUP BY cc.enroll_type

SELECT DATE_FORMAT(cs.session_date, '%Y年%m月') AS month, SUM((SELECT COUNT(*) FROM t_as_attendance_record ar WHERE ar.session_id = cs.id AND ar.target_type = 1 AND ar.attendance_status in (1,2,3) AND ar.is_valid = 1
AND ar.student_id IN
#{id}
)) AS attendanceCount, SUM((SELECT COUNT(*) FROM t_as_attendance_record ar WHERE ar.session_id = cs.id AND ar.target_type = 1 AND ar.is_valid = 1
AND ar.student_id IN
#{id}
)) AS totalCount FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cs.is_valid = 1 AND cs.school_id = #{schoolId}
AND svc.term_id = #{ydqsTermId}
GROUP BY DATE_FORMAT(cs.session_date, '%Y年%m月') ORDER BY DATE_FORMAT(cs.session_date, '%Y-%m') ASC

SELECT
    s.gender AS gender,
    COUNT(s.id) AS cnt
FROM t_as_student s
WHERE s.is_valid = 1
  and s.register_status = 1
  AND s.school_id = #{schoolId}
  AND s.term_id = #{termId}

    AND s.grade_id = #{xbfbGradeId}

GROUP BY s.gender

SELECT IFNULL(cat.category_name, '未分类') AS categoryName, COUNT(DISTINCT e.student_id) AS cnt FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_status NOT IN (0, 2) AND e.school_id = #{schoolId} AND s.term_id = svc.term_id
AND svc.term_id = #{xqfzTermId}
GROUP BY cc.category_id ORDER BY cnt DESC

SELECT cc.course_class_name AS courseClassName, COUNT(DISTINCT e.student_id) AS cnt FROM t_as_enrollment e INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_status NOT IN (0, 2) AND e.school_id = #{schoolId} AND s.term_id = svc.term_id
AND svc.term_id = #{xqfzTermId}
GROUP BY cc.id ORDER BY cnt DESC LIMIT 2

SELECT g.grade_name AS gradeName, COUNT(DISTINCT e.student_id) AS cnt FROM t_as_enrollment e INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 INNER JOIN t_as_student s ON e.student_id = s.id AND s.is_valid = 1 and s.register_status = 1 LEFT JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 WHERE e.is_valid = 1 AND e.enroll_status NOT IN (0, 2) AND e.school_id = #{schoolId} AND s.term_id = svc.term_id
AND svc.term_id = #{xqfzTermId}
GROUP BY s.grade_id ORDER BY cnt DESC LIMIT 1

SELECT
    (SELECT COUNT(DISTINCT e.student_id)
     FROM t_as_enrollment e
     INNER JOIN t_as_student s on s.id = e.student_id and s.is_valid = 1 AND s.register_status = 1 AND s.school_roll_status = 1
     INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1
     INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
     WHERE e.is_valid = 1
       AND e.enroll_status NOT IN (0, 2)
       AND e.school_id = #{schoolId}
       AND s.term_id = svc.term_id

           AND svc.term_id = #{xqfzTermId}

    ) AS enrolledCount,
    (SELECT COUNT(*)
     FROM t_as_student s
     WHERE s.is_valid = 1 AND s.register_status = 1
       AND s.school_roll_status = 1
       AND s.school_id = #{schoolId}
       AND s.term_id = #{xqfzTermId}
    ) AS totalStudentCount

SELECT CASE WHEN cc.enroll_type IN (1, 2) THEN '特色课程' WHEN cc.enroll_type = 3 THEN '行政课程' ELSE '其他' END AS name, COUNT(cc.id) AS value FROM t_as_course_class cc INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cc.is_valid = 1 AND cc.school_id = #{schoolId}
AND svc.term_id = #{termId}
GROUP BY name

SELECT FLOOR(DATEDIFF(cs.session_date, #{startDate}) / 7) + 1 AS weekNum, CONCAT('第', FLOOR(DATEDIFF(cs.session_date, #{startDate}) / 7) + 1, '周') AS weekLabel, COUNT(DISTINCT CASE WHEN ar.id IS NOT NULL AND ar.attendance_status NOT IN (4, 5) THEN ar.id END) AS attendanceCount, COUNT(DISTINCT CASE WHEN ar.id IS NOT NULL THEN ar.id END) AS totalCount FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_attendance_record ar ON ar.session_id = cs.id AND ar.is_valid = 1 AND ar.target_type = 1 WHERE cs.is_valid = 1 AND cs.school_id = #{schoolId}
AND svc.term_id = #{termId}
AND cs.session_date >= #{startDate}
AND cs.session_date <= #{endDate}
GROUP BY weekNum ORDER BY weekNum ASC

SELECT cc.course_class_name AS courseClassName, ROUND(AVG(ea.total_score), 2) AS avgScore FROM t_as_evaluation_answer ea INNER JOIN t_as_course_class cc ON ea.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE ea.is_valid = 1 AND ea.school_id = #{query.schoolId} AND ea.target_teacher_id IS NOT NULL AND ea.submit_status = 1 AND ea.total_score IS NOT NULL
AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.kcpjCategoryId}
GROUP BY ea.course_class_id ORDER BY avgScore DESC

SELECT cc.course_class_name AS courseClassName, COUNT(cs.id) AS lessonCount FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cs.is_valid = 1 AND cs.school_id = #{query.schoolId}
AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.zkstjCategoryId}
GROUP BY cs.course_class_id ORDER BY lessonCount DESC

SELECT cc.id AS courseClassId, cc.course_class_name AS courseClassName, COUNT(cs.id) AS totalClassHours, COUNT(CASE WHEN cs.session_status = 2 THEN cs.id END) AS finishedClassHours, COUNT(CASE WHEN cs.session_status IN (0, 1) THEN cs.id END) AS unfinishedClassHours FROM t_as_course_session cs INNER JOIN t_as_course_class cc ON cs.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE cs.is_valid = 1 AND cs.school_id = #{query.schoolId}
AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.kswcqkCategoryId}
GROUP BY cc.id ORDER BY totalClassHours DESC

SELECT cc.id AS courseClassId, cc.course_class_name AS courseClassName, t.teacher_name AS teacherName, ROUND(AVG(CASE WHEN ea.total_score IS NOT NULL THEN ea.total_score END), 2) AS avgScore, COUNT(DISTINCT CASE WHEN ar.id IS NOT NULL AND ar.attendance_status NOT IN (4, 5) THEN ar.id END) AS attendanceCount, COUNT(DISTINCT CASE WHEN ar.id IS NOT NULL THEN ar.id END) AS totalCount FROM t_as_course_class cc INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 AND svc.service_status != 0 LEFT JOIN t_as_teacher t ON cc.teacher_id = t.id AND t.is_valid = 1 LEFT JOIN t_as_evaluation_answer ea ON ea.course_class_id = cc.id AND ea.is_valid = 1 AND ea.target_teacher_id IS NOT NULL AND ea.submit_status = 1 LEFT JOIN t_as_course_session cs ON cs.course_class_id = cc.id AND cs.is_valid = 1 LEFT JOIN t_as_attendance_record ar ON ar.session_id = cs.id AND ar.is_valid = 1 AND ar.target_type = 1 WHERE cc.is_valid = 1 AND cc.school_id = #{query.schoolId}
AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.kcpfphCategoryId}
GROUP BY cc.id ORDER BY avgScore DESC

SELECT CASE WHEN cc.enroll_type IN (1, 2) THEN 0 WHEN cc.enroll_type = 3 THEN 1 ELSE 2 END AS categoryType, cc.category_id AS categoryId, cat.category_name AS categoryName, COUNT(cc.id) AS courseCount FROM t_as_course_class cc INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 WHERE cc.is_valid = 1 AND cc.school_id = #{schoolId}
AND svc.term_id = #{termId}
GROUP BY categoryType, cc.category_id

SELECT cc.id AS courseClassId, cc.course_class_name AS courseClassName, CONCAT( CASE WHEN cc.enroll_type IN (1, 2) THEN '特色课程' WHEN cc.enroll_type = 3 THEN '行政课程' ELSE '其他' END,'/',COALESCE(cat.category_name, '未分类') ) AS categoryPath, cc.applicable_grade_ids AS applicableGradeIds, t.teacher_name AS teacherName FROM t_as_course_class cc INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 LEFT JOIN t_as_teacher t ON cc.teacher_id = t.id AND t.is_valid = 1
cc.is_valid = 1 AND cc.school_id = #{query.schoolId}
AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.categoryId}
AND t.teacher_name LIKE CONCAT('%', #{query.teacherName}, '%')
AND JSON_CONTAINS(cc.applicable_grade_ids, CAST(#{query.gradeId} AS JSON))
ORDER BY cc.create_time DESC

SELECT COUNT(DISTINCT ea.id)
FROM t_as_evaluation_answer ea
     INNER JOIN t_as_course_class cc ON ea.course_class_id = cc.id AND cc.is_valid = 1
     INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
WHERE ea.is_valid = 1
  AND ea.submit_status = 1
  AND ea.target_teacher_id IS NOT NULL
  AND svc.term_id = #{termId}
  AND ea.school_id = #{schoolId}

    AND cc.category_id = #{categoryId}


    AND cc.id = #{classId}

SELECT 'adminCount' AS statType, COUNT(DISTINCT ru.user_id) AS statCount
FROM t_role_user ru
WHERE ru.role_id IN (1, 4)

UNION ALL

SELECT 'courseCount' AS statType, COUNT(DISTINCT cc.id) AS statCount
FROM t_as_course_class cc
INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
WHERE cc.is_valid = 1
  AND svc.term_id = #{termId}
  AND cc.school_id = #{schoolId}

    AND cc.category_id = #{categoryId}


    AND cc.id = #{classId}


UNION ALL

SELECT 'enrolledStudentCount' AS statType, COUNT(DISTINCT e.student_id) AS statCount
FROM t_as_enrollment e
INNER JOIN t_as_course_class cc ON e.course_class_id = cc.id AND cc.is_valid = 1
INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
WHERE e.is_valid = 1
  AND e.enroll_status IN (1, 3)
  AND svc.term_id = #{termId}
  AND e.school_id = #{schoolId}

    AND cc.category_id = #{categoryId}


    AND cc.id = #{classId}

SELECT CASE WHEN avg_score.avgScore < 60 THEN '60以下' WHEN avg_score.avgScore >= 60 AND avg_score.avgScore <= 69 THEN '60-69' WHEN avg_score.avgScore >= 70 AND avg_score.avgScore <= 79 THEN '70-79' WHEN avg_score.avgScore >= 80 AND avg_score.avgScore <= 89 THEN '80-89' WHEN avg_score.avgScore >= 90 AND avg_score.avgScore <= 100 THEN '90-100' END AS scoreRange, COUNT(*) AS courseCount FROM ( SELECT cc.id AS courseClassId, AVG(CASE WHEN ea.total_score IS NOT NULL THEN ea.total_score END) AS avgScore FROM t_as_evaluation_answer ea INNER JOIN t_as_course_class cc ON ea.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 WHERE ea.is_valid = 1 AND ea.school_id = #{query.schoolId} AND ea.target_teacher_id IS NOT NULL AND ea.submit_status = 1 AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.categoryId}
GROUP BY cc.id HAVING avgScore IS NOT NULL ) avg_score GROUP BY scoreRange

SELECT cc.id AS courseClassId, cc.course_class_name AS courseClassName, cat.category_name AS categoryName, t.teacher_name AS teacherName, ROUND(AVG(CASE WHEN ea.total_score IS NOT NULL THEN ea.total_score END), 2) AS averageScore, COUNT(DISTINCT ea.id) AS evaluationCount FROM t_as_course_class cc INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 AND svc.service_status != 0 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 LEFT JOIN t_as_teacher t ON cc.teacher_id = t.id AND t.is_valid = 1 LEFT JOIN t_as_evaluation_answer ea ON ea.course_class_id = cc.id AND ea.is_valid = 1 AND ea.target_teacher_id IS NOT NULL AND ea.submit_status = 1 WHERE cc.is_valid = 1 AND cc.school_id = #{query.schoolId} AND svc.term_id = #{query.termId}
AND cc.category_id = #{query.categoryId}
GROUP BY cc.id, cc.course_class_name, cat.category_name, t.teacher_name
ORDER BY averageScore DESC
ORDER BY evaluationCount DESC
ORDER BY cc.create_time DESC

SELECT IFNULL(cat.category_name, '未分类') AS name, COUNT(sd.id) AS value FROM t_as_course_session sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1 LEFT JOIN t_as_course_category cat ON cc.category_id = cat.id AND cat.is_valid = 1 WHERE sd.is_valid = 1
AND sd.school_id = #{schoolId}
AND svc.term_id = #{termId}
AND sd.teacher_id = #{teacherId}
GROUP BY cc.category_id ORDER BY value DESC

select
    (SELECT COUNT(DISTINCT sd.id)
     FROM t_as_course_session sd
          INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1
          INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
     WHERE sd.is_valid = 1
       AND sd.school_id = #{schoolId}
       AND sd.original_teacher_id = #{teacherId}
       AND svc.term_id = #{termId}) AS totalLessonHours,
    (SELECT COUNT(DISTINCT CASE WHEN  cc.teacher_id = sd.teacher_id THEN sd.id END)
     FROM t_as_course_session sd
          INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1
          INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
     WHERE sd.is_valid = 1 and sd.session_status = 2
       AND sd.school_id = #{schoolId}
       AND sd.teacher_id = #{teacherId}
       AND svc.term_id = #{termId}) AS completedLessonHours,
    (SELECT count(cs.id) FROM t_as_course_session cs
        INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.teacher_id != cs.teacher_id and cc.is_valid = 1
        INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
    WHERE cc.teacher_id = #{teacherId}
          AND cs.school_id = #{schoolId}
          AND svc.term_id = #{termId}
          AND cs.session_status = 2
          AND cs.is_valid = 1 AND cs.adjust_status = 1
    ) AS adjustedSessions,
    ( SELECT count(cs.id) FROM t_as_course_session cs
        INNER JOIN t_as_course_class cc on cc.id = cs.course_class_id and cc.teacher_id != cs.teacher_id and cc.is_valid = 1
        INNER JOIN t_as_service svc ON cc.service_id = svc.id AND svc.is_valid = 1
    WHERE cs.teacher_id = #{teacherId}
         AND svc.term_id = #{termId}
         AND cs.school_id = #{schoolId}
         AND cs.session_status = 2 AND cs.is_valid = 1 AND cs.adjust_status = 1
    ) AS substituteSessions

SELECT s.student_no AS studentNo, s.student_name AS studentName, s.gender, g.grade_name AS gradeName, c.class_name AS className FROM t_as_student s INNER JOIN ( SELECT MAX(id) AS max_id FROM t_as_student WHERE is_valid = 1 AND school_id = #{query.schoolId}
AND student_name LIKE CONCAT('%', #{query.studentName}, '%')
AND grade_id = #{query.gradeId}
AND class_id = #{query.classId}
GROUP BY student_identity_id ) tmp ON s.id = tmp.max_id LEFT JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 LEFT JOIN t_educl_class c ON s.class_id = c.id AND c.is_valid = 1 WHERE s.is_valid = 1 ORDER BY s.class_id ASC, s.student_no ASC

SELECT ( SELECT CASE COUNT(*) WHEN 0 THEN NULL ELSE ROUND(SUM(CASE WHEN ar.attendance_status IN (1,2,3) THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) END FROM t_as_attendance_record ar WHERE ar.is_valid = 1 AND ar.target_type = 1 AND ar.student_id IN
#{id}
) AS attendanceRate, ( SELECT ROUND(AVG(ea.total_score), 2) FROM t_as_evaluation_answer ea WHERE ea.is_valid = 1 and ea.submit_status = 1 AND ea.target_student_id IN
#{id}
AND ea.total_score IS NOT NULL ) AS comprehensiveScore

SELECT cc.id AS courseId, cc.course_class_name AS courseName, tch.teacher_name AS teacherName, t.term_name AS termName, CASE WHEN COUNT(cs.id) = 0 THEN '0.00%' ELSE CONCAT( ROUND(SUM(CASE WHEN cs.session_status = 2 THEN 1 ELSE 0 END) * 100.0 / COUNT(cs.id), 2), '%' ) END AS courseCompletion FROM t_as_student_destination sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_service sv ON cc.service_id = sv.id AND sv.is_valid = 1 INNER JOIN t_educl_term t ON sv.term_id = t.id and t.is_valid = 1 INNER JOIN t_as_teacher tch ON cc.teacher_id = tch.id AND tch.is_valid = 1 INNER JOIN t_as_course_session cs ON cs.course_class_id = cc.id AND cs.is_valid = 1 WHERE sd.is_valid = 1 AND sd.course_class_id IS NOT NULL AND sd.student_id IN
#{id}
GROUP BY cc.id

SELECT cg.category_name AS name, COUNT(DISTINCT cc.id) AS value FROM t_as_student_destination sd INNER JOIN t_as_course_class cc ON sd.course_class_id = cc.id AND cc.is_valid = 1 INNER JOIN t_as_course_category cg ON cc.category_id = cg.id AND cg.is_valid = 1 WHERE sd.is_valid = 1 AND sd.course_class_id IS NOT NULL AND sd.student_id IN
#{id}
GROUP BY cc.category_id

SELECT a.id, t.teacher_name AS teacherName, cc.course_class_name AS courseClassName, a.submit_time AS submitTime, a.total_score AS totalScore FROM t_as_evaluation_answer a LEFT JOIN t_as_teacher t ON t.user_id = a.evaluator_user_id AND t.is_valid = 1 LEFT JOIN t_as_course_class cc ON cc.id = a.course_class_id AND cc.is_valid = 1 WHERE a.is_valid = 1 AND a.submit_status = 1 AND a.target_student_id IN
#{id}
ORDER BY a.submit_time DESC
